import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'auth_providers.dart';import 'otp_screen.dart';
class RegisterScreen extends ConsumerStatefulWidget{const RegisterScreen({super.key});@override ConsumerState<RegisterScreen>createState()=>_RegisterState();}class _RegisterState extends ConsumerState<RegisterScreen>{final form=GlobalKey<FormState>();final name=TextEditingController(),phone=TextEditingController(),email=TextEditingController(),password=TextEditingController();bool loading=false;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Register')),body:Form(key:form,child:ListView(padding:const EdgeInsets.all(24),children:[TextFormField(controller:name,decoration:const InputDecoration(labelText:'Name'),validator:(v)=>v==null||v.isEmpty?'Name required':null),TextFormField(controller:phone,decoration:const InputDecoration(labelText:'Phone'),validator:(v)=>v==null||v.isEmpty?'Phone required':null),TextFormField(controller:email,decoration:const InputDecoration(labelText:'Email (optional)'),validator:(v)=>v!=null&&v.isNotEmpty&&!v.contains('@')?'Invalid email':null),TextFormField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password'),validator:(v)=>v==null||v.length<8?'Minimum 8 characters':null),const SizedBox(height:20),FilledButton(onPressed:loading?null:()async{if(!form.currentState!.validate())return;setState(()=>loading=true);try{await ref.read(authSessionProvider.notifier).register(name:name.text,phone:phone.text,email:email.text.isEmpty?null:email.text,password:password.text);if(mounted)Navigator.push(context,MaterialPageRoute(builder:(_)=>OtpScreen(phone:phone.text)));}finally{if(mounted)setState(()=>loading=false);}},child:Text(loading?'Loading…':'Create account'))])));}
